<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{api}from'../../api';import{useCartStore}from'../../stores/cart';import type{Product}from'../../types';const product=ref<Product>(),cart=useCartStore();onLoad(async(q)=>{await cart.load();product.value=await api.product(String(q?.id||'p001'))});const add=async()=>{if(product.value){await cart.set(product.value,cart.quantity(product.value.id)+1);uni.showToast({title:'已放进购物袋',icon:'success'})}}</script>
<template><view v-if="product" class="detail"><view class="visual"><image :src="product.image" mode="aspectFit" :alt="product.name"/><text class="visual__tag">{{product.tag}}</text></view><view class="content"><view class="card info"><text class="info__name">{{product.name}}</text><text class="info__sub">{{product.subtitle}}</text><view class="info__price"><text class="price"><text class="price__symbol">¥</text>{{product.price}}</text><text class="original">¥{{product.originalPrice}}</text><text class="sales">已送到 {{product.sales}} 间寝室</text></view></view><view class="card guarantee"><view><text class="guarantee__title">校园仓现货</text><text class="muted">库存 {{product.stock}} 件</text></view><view><text class="guarantee__title">最快 30 分钟</text><text class="muted">楼长送到寝室</text></view></view><view class="story"><text class="story__eyebrow">今晚的快乐很简单</text><text class="story__title">不用换鞋，不用下楼。</text><text class="muted">下单后从湖工大校园仓出发，经配送员送到楼下，再由楼长送到你的寝室门口。</text></view></view><view class="bottom safe-bottom"><button class="bag" @tap="uni.switchTab({url:'/pages/cart/index'})">购物袋 {{cart.cart.totalQuantity||''}}</button><button class="primary-btn" @tap="add">加入购物袋</button></view></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.detail{min-height:100vh;background:$paper;padding-bottom:150rpx}.visual{height:650rpx;background:radial-gradient(circle at 50% 45%,#fff 0,#ffefd9 50%,#ffd8c8 100%);position:relative}.visual image{width:100%;height:100%}.visual__tag{position:absolute;left:32rpx;bottom:30rpx;background:$ink;color:#fff;padding:12rpx 22rpx;border-radius:28rpx;font-weight:800}.content{padding:0 28rpx;margin-top:-10rpx}.info{padding:32rpx}.info__name{display:block;font-size:44rpx;font-weight:900}.info__sub{display:block;color:$muted;margin-top:10rpx}.info__price{display:flex;align-items:baseline;gap:16rpx;margin-top:28rpx}.info__price .price{font-size:48rpx}.original{text-decoration:line-through;color:$muted}.sales{margin-left:auto;font-size:22rpx;color:$muted}.guarantee{display:grid;grid-template-columns:1fr 1fr;margin-top:22rpx;padding:26rpx}.guarantee>view+view{border-left:2rpx solid $line;padding-left:28rpx}.guarantee__title{display:block;font-weight:800;margin-bottom:6rpx}.story{padding:48rpx 10rpx}.story__eyebrow{color:$primary-dark;font-weight:800}.story__title{display:block;font-size:38rpx;font-weight:900;margin:14rpx 0;line-height:1.4}.bottom{position:fixed;left:0;right:0;bottom:0;background:#fff;padding:18rpx 28rpx;display:flex;gap:18rpx;box-shadow:0 -10rpx 30rpx rgba(47,38,34,.08)}.bottom button{margin:0}.bag{width:220rpx;border-radius:46rpx;background:#fff0e6;color:$primary-dark;font-weight:800}.bottom .primary-btn{flex:1}</style>
